INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('4441c61a-dc2b-58e4-af65-a21c59932087', '2ac7718c-4ff6-567c-a8bb-3eeaaca3d612', 'published', 'Life Polska Elizia', 'PL', NULL, NULL, 'Sauna ogrodowa z dużym przesuwnym oknem tarasowym, w większych wariantach z balią BW-17P. Przestronne przeszklenie daje piękny widok na otoczenie, a eleganckie wykończenie z drewna podkreśla stylowy charakter. Piec Diabaz jest ładowany od zewnątrz. Połączenie sauny z balią tworzy komfortową strefę relaksu na każdą porę roku.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '400 x 250 – 800 x 300 cm (wys. 245 cm)', 'Płaski dach pokryty blachą', 'Sauna z drewna naturalnego, wykończona drewnem, z drewnianą podłogą i linoleum w części przedsionkowej; w standardzie jest dach pokryty blachą', 'Sauna ustawiana na stabilnym, równym podłożu przygotowanym przez klienta (np. płyta, kostka lub fundament punktowy)', 'Wybór pieca (drewno lub elektryczny Harvia), oświetlenie, impregnacja, przeszklenie przesuwne tarasowe w długości od 2 do 6 m oraz dodatkowe wyposażenie.', 'EUR', NULL, NULL, false, '2026-11-11T10:16:02.154Z'::timestamptz, '2026-11-11T10:16:02.872Z'::timestamptz, NULL, 'spa-modulowe', 'sauna', '{"glazingType":"Duże przeszklenie z przesuwnym oknem tarasowym; szklane drzwi i front części saunowej","benchMaterial":"Drewniane ławeczki w naturalnym, nieimpregnowanym drewnie","insulationType":"Ściany drewniane grubości prawie 5 cm; sauna nagrzewa się do 80-110 °C w 30-45 minut","hasChangingArea":false,"seatingCapacity":2,"claddingMaterial":"Wykończenie z drewna naturalnego","interiorWoodType":"Naturalne, nieimpregnowane drewno (świerk, cedr syberyjski lub modrzew modyfikowany termicznie)","electricalRequirement":"Standardowy piec opalany drewnem Diabaz nie wymaga zasilania; opcjonalny piec elektryczny Harvia 9 kW (Cylindro) lub 11 kW (Legend Home) ze sterowaniem Wi-Fi"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'life-polska-elizia', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('51bcb3b8-0d07-5ddc-a7ac-e8dfcb73882f', '2ac7718c-4ff6-567c-a8bb-3eeaaca3d612', 'published', 'Life Polska Rąbek', 'PL', NULL, NULL, 'Nowoczesna sauna ogrodowa o prostej, geometrycznej formie. Elewacja z trwałej blachy w kolorze grafitowym nadaje jej elegancki, industrialny wygląd. Front stanowią duże przeszklone drzwi, które wpuszczają naturalne światło i pozwalają zobaczyć drewniane wnętrze. W środku są solidne ławy ze świerku i nowoczesny piec Diabaz ładowany od zewnątrz. Sauna na stabilnej podstawie sprawdzi się jako całoroczna strefa relaksu.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '200 x 200 – 600 x 240 cm (wys. 245 cm)', 'Dach pokryty blachą (kolor do wyboru: RAL 9010, 8017 lub 7016)', 'Elewacja z trwałej blachy w kolorze grafitowym, sauna na stabilnej podstawie, wnętrze z drewna naturalnego z drewnianą podłogą', 'Sauna ustawiana na stabilnym, równym podłożu przygotowanym przez klienta (np. płyta, kostka lub fundament punktowy)', NULL, 'EUR', NULL, NULL, false, '2026-11-11T10:16:08.939Z'::timestamptz, '2026-11-11T10:16:09.358Z'::timestamptz, NULL, 'spa-modulowe', 'sauna', '{"glazingType":"Duże przeszklone drzwi w froncie","benchMaterial":"Solidne ławy z drewna świerkowego","insulationType":"Ściany drewniane grubości prawie 5 cm; sauna nagrzewa się do 80-110 °C w 30-45 minut","hasChangingArea":true,"seatingCapacity":2,"claddingMaterial":"Trwała blacha w kolorze grafitowym","interiorWoodType":"Naturalne, nieimpregnowane drewno (świerk, cedr syberyjski lub modrzew modyfikowany termicznie)","electricalRequirement":"Standardowy piec opalany drewnem Diabaz nie wymaga zasilania; opcjonalny piec elektryczny Harvia 9 kW (Cylindro) lub 11 kW (Legend Home) ze sterowaniem Wi-Fi","changingAreaDescription":"Przedsionek w wariantach 400 x 240 cm i 600 x 240 cm"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'life-polska-rabek', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
