:16.545Z'::timestamptz, NULL, 'spa-modulowe', 'sauna', '{"glazingType":"Duże przeszklenia; szklane drzwi i front","benchMaterial":"Drewniane ławeczki w naturalnym, nieimpregnowanym drewnie","insulationType":"Ściany drewniane grubości prawie 5 cm; sauna nagrzewa się do 80-110 °C w 30-45 minut","hasChangingArea":true,"seatingCapacity":2,"claddingMaterial":"Lamele z naturalnego termodrewna","interiorWoodType":"Naturalne, nieimpregnowane drewno (świerk, cedr syberyjski lub modrzew modyfikowany termicznie)","electricalRequirement":"Standardowy piec opalany drewnem Diabaz nie wymaga zasilania; opcjonalny piec elektryczny Harvia 9 kW (Cylindro) lub 11 kW (Legend Home) ze sterowaniem Wi-Fi","changingAreaDescription":"Przedsionek w wariantach od 300 x 240 cm"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'life-polska-porto', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
