nktowy)', NULL, 'EUR', NULL, NULL, false, '2026-11-11T10:16:32.308Z'::timestamptz, '2026-11-11T10:16:32.712Z'::timestamptz, NULL, 'spa-modulowe', 'sauna', '{"glazingType":"Panoramiczne przeszklenia w ciemnych ramach; szklane drzwi","benchMaterial":"Drewniane ławeczki w naturalnym, nieimpregnowanym drewnie","insulationType":"Ściany drewniane grubości prawie 5 cm; sauna nagrzewa się do 80-110 °C w 30-45 minut","hasChangingArea":true,"seatingCapacity":2,"claddingMaterial":"Elementy drewniane z detalami w kolorze grafitowym","interiorWoodType":"Naturalne, nieimpregnowane drewno (świerk, cedr syberyjski lub modrzew modyfikowany termicznie)","electricalRequirement":"Standardowy piec opalany drewnem Diabaz nie wymaga zasilania; opcjonalny piec elektryczny Harvia 9 kW (Cylindro) lub 11 kW (Legend Home) ze sterowaniem Wi-Fi","changingAreaDescription":"Przedsionek w wariantach od 324 x 242 cm"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'life-polska-q-stka', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
