INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('6a3e6b8e-160d-56f4-af96-be78259d455f', '2ac7718c-4ff6-567c-a8bb-3eeaaca3d612', 'published', 'Life Polska Panorama', 'PL', NULL, NULL, 'Owalna sauna z okrągłym, panoramicznym przeszkleniem wypukłym z poliwęglanu. Ściany pionowe wykonane są z drewna klejonego z autorskim, wodoodpornym połączeniem belek, które zapobiega wnikaniu wody i wilgoci opadowej oraz przeciwdziała skutkom rozsychania drewna; rozwiązanie jest chronione prawem RP. Można używać pieca opalanego drewnem Diabaz albo elektrycznego Harvia.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '400 x 240 – 500 x 240 cm (wys. 215-225 cm)', 'Bez pokrycia w cenie bazowej; pokrycie blachą lub gontem bitumicznym (kolor do wyboru) jako opcja', 'Ściany pionowe z drewna klejonego z autorskim, wodoodpornym połączeniem belek (rozwiązanie chronione prawem RP); przeszklenie wypukłe z poliwęglanu', 'Sauna ustawiana na stabilnym, równym podłożu przygotowanym przez klienta (np. płyta, kostka lub fundament punktowy)', NULL, 'EUR', NULL, NULL, false, '2026-11-11T10:16:41.987Z'::timestamptz, '2026-11-11T10:16:42.336Z'::timestamptz, NULL, 'spa-modulowe', 'sauna', '{"glazingType":"Przeszklenie wypukłe z poliwęglanu; szklane drzwi zewnętrzne i wewnętrzne","benchMaterial":"Drewniane ławeczki w naturalnym, nieimpregnowanym drewnie","insulationType":"Ściany drewniane grubości prawie 5 cm; sauna nagrzewa się do 80-110 °C w 30-45 minut","hasChangingArea":true,"seatingCapacity":6,"claddingMaterial":"Drewno klejone, ściany pionowe z wodoodpornym połączeniem belek","interiorWoodType":"Naturalne, nieimpregnowane drewno (świerk, cedr syberyjski lub modrzew modyfikowany termicznie)","electricalRequirement":"Standardowy piec opalany drewnem Diabaz nie wymaga zasilania; opcjonalny piec elektryczny Harvia 9 kW (Cylindro) lub 11 kW (Legend Home) ze sterowaniem Wi-Fi","changingAreaDescription":"Przedsionek w obu wariantach"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'life-polska-panorama', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
