ytanie.', 'EUR', NULL, NULL, false, '2026-11-11T10:16:46.088Z'::timestamptz, '2026-11-11T10:16:46.815Z'::timestamptz, NULL, 'spa-modulowe', 'sauna', '{"glazingType":"Szklane drzwi zewnętrzne","benchMaterial":"Drewniane ławeczki w naturalnym, nieimpregnowanym drewnie","insulationType":"Ściany drewniane grubości prawie 5 cm; sauna nagrzewa się do 80-110 °C w 30-45 minut","hasChangingArea":true,"seatingCapacity":2,"claddingMaterial":"Naturalne drewno","interiorWoodType":"Naturalne, nieimpregnowane drewno (świerk, cedr syberyjski lub modrzew modyfikowany termicznie)","electricalRequirement":"Standardowy piec opalany drewnem Diabaz nie wymaga zasilania; opcjonalny piec elektryczny Harvia 9 kW (Cylindro) lub 11 kW (Legend Home) ze sterowaniem Wi-Fi","changingAreaDescription":"Przedsionek w wariantach M4P, M5P i M6P; podział modułów do ustalenia"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'life-polska-horyzont', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
