INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('65b635a4-fcf6-5222-adf5-10d5feae09c9', '2ac7718c-4ff6-567c-a8bb-3eeaaca3d612', 'published', 'Life Polska Beczka', 'PL', NULL, NULL, 'Sauna beczkowa z własnym piecem Diabaz: nadaje się do bezpośredniego polewania wodą i utrzymuje żądaną wilgotność dzięki parownikowi dozującemu. Ma otwory zasypowy i rewizyjny usytuowane na zewnątrz, więc nie trzeba wnosić do sauny opału ani jej wietrzyć, a zewnętrzna obsługa pieca zapobiega dostawaniu się dymu do wnętrza. Do wyboru jest także piec elektryczny Harvia.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Ø 200 x 165 – 400 cm (wys. 215 cm)', 'Bez pokrycia w cenie bazowej; pokrycie blachą lub gontem bitumicznym (kolor do wyboru) jako opcja', 'Beczka z naturalnego drewna z piecem Diabaz obsługiwanym od zewnątrz', 'Sauna ustawiana na stabilnym, równym podłożu przygotowanym przez klienta (np. płyta, kostka lub fundament punktowy)', 'Opcjonalnie dodatkowy daszek, przedsionek oraz przeszklony front lub tył (dopłaty według cennika producenta).', 'EUR', NULL, NULL, false, '2026-11-11T10:16:51.244Z'::timestamptz, '2026-11-11T10:16:51.756Z'::timestamptz, NULL, 'spa-modulowe', 'sauna', '{"glazingType":"Szklane drzwi zewnętrzne","benchMaterial":"Drewniane ławeczki w naturalnym, nieimpregnowanym drewnie","insulationType":"Ściany drewniane grubości prawie 5 cm; sauna nagrzewa się do 80-110 °C w 30-45 minut","hasChangingArea":true,"seatingCapacity":2,"claddingMaterial":"Naturalne drewno, dach z gontu bitumicznego lub blachy","interiorWoodType":"Naturalne, nieimpregnowane drewno (świerk, cedr syberyjski lub modrzew modyfikowany termicznie)","electricalRequirement":"Standardowy piec opalany drewnem Diabaz nie wymaga zasilania; opcjonalny piec elektryczny Harvia 9 kW (Cylindro) lub 11 kW (Legend Home) ze sterowaniem Wi-Fi","changingAreaDescription":"Przedsionek w wariantach SO-3B i SO-4B"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'life-polska-beczka', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('b8b93a9c-6d89-467e-b4b1-57ee87f9e8d8', '4441c61a-dc2b-58e4-af65-a21c59932087', 'en', NULL, 'A garden sauna with a large sliding terrace window and, in the larger versions, a BW-17P hot tub. The spacious glazing gives a beautiful view of the surroundings, and the elegant wood finish underlines its stylish character. The Diabaz stove is fed from the outside. Combining the sauna with a hot tub creates a comfortable relaxation zone for every season.', '2026-11-11T10:16:02.154Z'::timestamptz, '2026-11-11T10:16:02.154Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The sauna is placed on a stable, level base prepared by the customer (e.g. a slab, paving or point foundations)', '{"specs":{"glazingType":{"value":"Large glazing with a sliding terrace window; glass door and front of the sauna part"},"benchMaterial":{"value":"Wooden benches in natural, untreated wood"},"insulationType":{"value":"Wooden walls almost 5 cm thick; the sauna heats up to 80-110 °C in 30-45 minutes"},"claddingMaterial":{"value":"Natural wood finish"},"interiorWoodType":{"value":"Natural, untreated wood (spruce, Siberian cedar or thermally modified larch)"},"electricalRequirement":{"value":"The standard wood-fired Diabaz stove needs no power supply; an optional Harvia electric stove, 9 kW (Cylindro) or 11 kW (Legend Home), with Wi-Fi control"}}}'::jsonb, 'Natural wood sauna with a wood finish, wooden floor and linoleum in the vestibule part; the standard roof is covered with sheet metal', 'Flat sheet metal roof', 'Choice of stove (wood or Harvia electric), lighting, impregnation, sliding terrace glazing from 2 to 6 m in length and additional equipment.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('cb34b384-a787-4768-85a0-7660630cc237', '4441c61a-dc2b-58e4-af65-a21c59932087', 'de', NULL, 'Gartensauna mit großem Terrassen-Schiebefenster, in den größeren Varianten mit Badefass BW-17P. Die geräumige Verglasung bietet einen schönen Blick auf die Umgebung, und die elegante Holzverkleidung unterstreicht ihren stilvollen Charakter. Der Ofen Diabaz wird von außen beschickt. Die Kombination aus Sauna und Badefass schafft eine komfortable Entspannungszone für jede Jahreszeit.', '2026-11-11T10:16:02.154Z'::timestamptz, '2026-11-11T10:16:02.154Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Die Sauna wird auf einem stabilen, ebenen, vom Kunden vorbereiteten Untergrund aufgestellt (z. B. Platte, Pflaster oder Punktfundamente)', '{"specs":{"glazingType":{"value":"Große Verglasung mit Terrassen-Schiebefenster; Glastür und Front des Saunabereichs"},"benchMaterial":{"value":"Holzbänke aus naturbelassenem, unbehandeltem Holz"},"insulationType":{"value":"Holzwände von knapp 5 cm Stärke; die Sauna heizt sich in 30-45 Minuten auf 80-110 °C auf"},"claddingMaterial":{"value":"Verkleidung aus Naturholz"},"interiorWoodType":{"value":"Naturbelassenes, unbehandeltes Holz (Fichte, sibirische Zeder oder thermisch modifizierte Lärche)"},"electricalRequirement":{"value":"Der Standardofen Diabaz (Holzfeuerung) benötigt keinen Stromanschluss; optional Harvia-Elektroofen 9 kW (Cylindro) oder 11 kW (Legend Home) mit WLAN-Steuerung"}}}'::jsonb, 'Sauna aus Naturholz mit Holzverkleidung, Holzboden und Linoleum im Vorraumbereich; das Dach ist serienmäßig mit Blech gedeckt', 'Flachdach mit Blechdeckung', 'Wahl des Ofens (Holz oder Harvia-Elektro), Beleuchtung, Imprägnierung, Terrassen-Schiebeverglasung in einer Länge von 2 bis 6 m und Zusatzausstattung.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('d602ad0e-10bf-42da-a5ae-3d0e8d991483', '4441c61a-dc2b-58e4-af65-a21c59932087', 'nl', NULL, 'Tuinsauna met een groot schuifraam naar het terras en in de grotere uitvoeringen met een hottub BW-17P. De ruime beglazing geeft een prachtig uitzicht op de omgeving en de elegante houtafwerking onderstreept het stijlvolle karakter. De Diabaz-kachel wordt van buitenaf gestookt. De combinatie van sauna en hottub vormt een comfortabele ontspanningszone voor elk seizoen.', '2026-11-11T10:16:02.154Z'::timestamptz, '2026-11-11T10:16:02.154Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'De sauna wordt geplaatst op een stabiele, vlakke ondergrond die de klant voorbereidt (bijv. een plaat, bestrating of puntfunderingen)', '{"specs":{"glazingType":{"value":"Grote beglazing met een schuifraam naar het terras; glazen deur en front van het saunadeel"},"benchMaterial":{"value":"Houten banken van natuurlijk, onbehandeld hout"},"insulationType":{"value":"Houten wanden van bijna 5 cm dik; de sauna warmt in 30-45 minuten op tot 80-110 °C"},"claddingMaterial":{"value":"Afwerking van natuurlijk hout"},"interiorWoodType":{"value":"Natuurlijk, onbehandeld hout (vuren, Siberische ceder of thermisch gemodificeerd lariks)"},"electricalRequirement":{"value":"De standaard houtgestookte Diabaz-kachel heeft geen stroomaansluiting nodig; optioneel een elektrische Harvia-kachel van 9 kW (Cylindro) of 11 kW (Legend Home) met wifi-besturing"}}}'::jsonb, 'Sauna van natuurlijk hout met houtafwerking, houten vloer en linoleum in het voorruimtedeel; het standaarddak is met plaat bedekt', 'Plat dak met plaatbedekking', 'Keuze van kachel (hout of elektrische Harvia), verlichting, impregnering, schuifbeglazing voor het terras met een lengte van 2 tot 6 m en extra uitrusting.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('bcf0c823-6005-446b-929c-16a89c18a6f8', '51bcb3b8-0d07-5ddc-a7ac-e8dfcb73882f', 'en', NULL, 'A modern garden sauna with a simple, geometric form. The facade of durable sheet metal in graphite gives it an elegant, industrial look. The front is made of large glass doors that let in natural light and show the wooden interior. Inside are solid spruce benches and a modern Diabaz stove fed from the outside. Set on a stable base, the sauna works as a year-round relaxation zone.', '2026-11-11T10:16:08.939Z'::timestamptz, '2026-11-11T10:16:08.939Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The sauna is placed on a stable, level base prepared by the customer (e.g. a slab, paving or point foundations)', '{"specs":{"glazingType":{"value":"Large glass doors in the front"},"benchMaterial":{"value":"Solid spruce benches"},"insulationType":{"value":"Wooden walls almost 5 cm thick; the sauna heats up to 80-110 °C in 30-45 minutes"},"claddingMaterial":{"value":"Durable sheet metal in graphite"},"interiorWoodType":{"value":"Natural, untreated wood (spruce, Siberian cedar or thermally modified larch)"},"electricalRequirement":{"value":"The standard wood-fired Diabaz stove needs no power supply; an optional Harvia electric stove, 9 kW (Cylindro) or 11 kW (Legend Home), with Wi-Fi control"},"changingAreaDescription":{"value":"Vestibule in the 400 x 240 cm and 600 x 240 cm versions"}}}'::jsonb, 'Facade of durable graphite sheet metal, sauna on a stable base, interior of natural wood with a wooden floor', 'Sheet metal roof (colour to choose: RAL 9010, 8017 or 7016)', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('fd6f39e0-e36e-4092-b003-b620ff51acfd', '51bcb3b8-0d07-5ddc-a7ac-e8dfcb73882f', 'de', NULL, 'Moderne Gartensauna in schlichter, geometrischer Form. Die Fassade aus widerstandsfähigem Blech in Graphit verleiht ihr ein elegantes, industrielles Aussehen. Die Front besteht aus großen Glastüren, die natürliches Licht hereinlassen und den Blick auf das Holzinnere freigeben. Im Inneren befinden sich massive Fichtenbänke und ein moderner, von außen beschickter Ofen Diabaz. Auf einem stabilen Sockel eignet sich die Sauna als ganzjährige Entspannungszone.', '2026-11-11T10:16:08.939Z'::timestamptz, '2026-11-11T10:16:08.939Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Die Sauna wird auf einem stabilen, ebenen, vom Kunden vorbereiteten Untergrund aufgestellt (z. B. Platte, Pflaster oder Punktfundamente)', '{"specs":{"glazingType":{"value":"Große Glastüren in der Front"},"benchMaterial":{"value":"Massive Fichtenbänke"},"insulationType":{"value":"Holzwände von knapp 5 cm Stärke; die Sauna heizt sich in 30-45 Minuten auf 80-110 °C auf"},"claddingMaterial":{"value":"Widerstandsfähiges Blech in Graphit"},"interiorWoodType":{"value":"Naturbelassenes, unbehandeltes Holz (Fichte, sibirische Zeder oder thermisch modifizierte Lärche)"},"electricalRequirement":{"value":"Der Standardofen Diabaz (Holzfeuerung) benötigt keinen Stromanschluss; optional Harvia-Elektroofen 9 kW (Cylindro) oder 11 kW (Legend Home) mit WLAN-Steuerung"},"changingAreaDescription":{"value":"Vorraum in den Varianten 400 x 240 cm und 600 x 240 cm"}}}'::jsonb, 'Fassade aus widerstandsfähigem Graphitblech, Sauna auf stabilem Sockel, Innenraum aus Naturholz mit Holzboden', 'Dach mit Blechdeckung (Farbe nach Wahl: RAL 9010, 8017 oder 7016)', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('5569f21c-6a95-4188-82e0-529039cb9ff8', '51bcb3b8-0d07-5ddc-a7ac-e8dfcb73882f', 'nl', NULL, 'Moderne tuinsauna met een eenvoudige, geometrische vorm. De gevel van duurzame plaat in grafiet geeft haar een elegante, industriële uitstraling. De voorzijde bestaat uit grote glazen deuren die natuurlijk licht binnenlaten en het houten interieur laten zien. Binnen staan stevige vurenhouten banken en een moderne Diabaz-kachel die van buitenaf wordt gestookt. Op een stabiele ondergrond is de sauna een ontspanningszone voor het hele jaar.', '2026-11-11T10:16:08.939Z'::timestamptz, '2026-11-11T10:16:08.939Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'De sauna wordt geplaatst op een stabiele, vlakke ondergrond die de klant voorbereidt (bijv. een plaat, bestrating of puntfunderingen)', '{"specs":{"glazingType":{"value":"Grote glazen deuren in de voorzijde"},"benchMaterial":{"value":"Stevige vurenhouten banken"},"insulationType":{"value":"Houten wanden van bijna 5 cm dik; de sauna warmt in 30-45 minuten op tot 80-110 °C"},"claddingMaterial":{"value":"Duurzame plaat in grafiet"},"interiorWoodType":{"value":"Natuurlijk, onbehandeld hout (vuren, Siberische ceder of thermisch gemodificeerd lariks)"},"electricalRequirement":{"value":"De standaard houtgestookte Diabaz-kachel heeft geen stroomaansluiting nodig; optioneel een elektrische Harvia-kachel van 9 kW (Cylindro) of 11 kW (Legend Home) met wifi-besturing"},"changingAreaDescription":{"value":"Voorruimte in de uitvoeringen van 400 x 240 cm en 600 x 240 cm"}}}'::jsonb, 'Gevel van duurzame grafietkleurige plaat, sauna op een stabiele basis, interieur van natuurlijk hout met een houten vloer', 'Dak met plaatbedekking (kleur naar keuze: RAL 9010, 8017 of 7016)', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('33dfd0b8-6ba6-48fa-9bb2-c094c9a5fc6b', 'a20d51b1-39e4-54e7-a07b-154d237f20a2', 'en', NULL, 'A modern sauna clad in thermally modified wood slats that combines an elegant, minimalist design with durability and functionality. The facade of natural thermowood resists moisture and changing weather. Large glazing brightens the interior and lets you relax in close contact with the surroundings. The Diabaz stove is fed from the outside.', '2026-11-11T10:16:15.994Z'::timestamptz, '2026-11-11T10:16:15.994Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The sauna is placed on a stable, level base prepared by the customer (e.g. a slab, paving or point foundations)', '{"specs":{"glazingType":{"value":"Large glazing; glass door and front"},"benchMaterial":{"value":"Wooden benches in natural, untreated wood"},"insulationType":{"value":"Wooden walls almost 5 cm thick; the sauna heats up to 80-110 °C in 30-45 minutes"},"claddingMaterial":{"value":"Slats of natural thermowood"},"interiorWoodType":{"value":"Natural, untreated wood (spruce, Siberian cedar or thermally modified larch)"},"electricalRequirement":{"value":"The standard wood-fired Diabaz stove needs no power supply; an optional Harvia electric stove, 9 kW (Cylindro) or 11 kW (Legend Home), with Wi-Fi control"},"changingAreaDescription":{"value":"Vestibule in the versions from 300 x 240 cm"}}}'::jsonb, 'Facade of natural thermowood slats, natural untreated wood inside, wooden floor', 'Flat sheet metal roof', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('1795c1c7-8ad1-41d7-9f3b-3ee20ecea3dc', 'a20d51b1-39e4-54e7-a07b-154d237f20a2', 'de', NULL, 'Moderne Sauna mit Lamellen aus thermisch modifiziertem Holz, die elegantes, minimalistisches Design mit Haltbarkeit und Funktionalität verbindet. Die Fassade aus naturbelassenem Thermoholz ist feuchtigkeits- und witterungsbeständig. Große Verglasungen erhellen den Innenraum und ermöglichen Entspannung in engem Kontakt mit der Umgebung. Der Ofen Diabaz wird von außen beschickt.', '2026-11-11T10:16:15.994Z'::timestamptz, '2026-11-11T10:16:15.994Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Die Sauna wird auf einem stabilen, ebenen, vom Kunden vorbereiteten Untergrund aufgestellt (z. B. Platte, Pflaster oder Punktfundamente)', '{"specs":{"glazingType":{"value":"Große Verglasungen; Glastür und Front"},"benchMaterial":{"value":"Holzbänke aus naturbelassenem, unbehandeltem Holz"},"insulationType":{"value":"Holzwände von knapp 5 cm Stärke; die Sauna heizt sich in 30-45 Minuten auf 80-110 °C auf"},"claddingMaterial":{"value":"Lamellen aus naturbelassenem Thermoholz"},"interiorWoodType":{"value":"Naturbelassenes, unbehandeltes Holz (Fichte, sibirische Zeder oder thermisch modifizierte Lärche)"},"electricalRequirement":{"value":"Der Standardofen Diabaz (Holzfeuerung) benötigt keinen Stromanschluss; optional Harvia-Elektroofen 9 kW (Cylindro) oder 11 kW (Legend Home) mit WLAN-Steuerung"},"changingAreaDescription":{"value":"Vorraum in den Varianten ab 300 x 240 cm"}}}'::jsonb, 'Fassade aus Lamellen aus naturbelassenem Thermoholz, innen naturbelassenes unbehandeltes Holz, Holzboden', 'Flachdach mit Blechdeckung', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('f4184ecd-8944-43b2-ab4b-26417e89f7e6', 'a20d51b1-39e4-54e7-a07b-154d237f20a2', 'nl', NULL, 'Moderne sauna bekleed met lamellen van thermisch gemodificeerd hout, die elegant, minimalistisch design combineert met duurzaamheid en functionaliteit. De gevel van natuurlijk thermohout is bestand tegen vocht en wisselende weersomstandigheden. Grote beglazing verlicht het interieur en laat je ontspannen in nauw contact met de omgeving. De Diabaz-kachel wordt van buitenaf gestookt.', '2026-11-11T10:16:15.994Z'::timestamptz, '2026-11-11T10:16:15.994Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'De sauna wordt geplaatst op een stabiele, vlakke ondergrond die de klant voorbereidt (bijv. een plaat, bestrating of puntfunderingen)', '{"specs":{"glazingType":{"value":"Grote beglazing; glazen deur en front"},"benchMaterial":{"value":"Houten banken van natuurlijk, onbehandeld hout"},"insulationType":{"value":"Houten wanden van bijna 5 cm dik; de sauna warmt in 30-45 minuten op tot 80-110 °C"},"claddingMaterial":{"value":"Lamellen van natuurlijk thermohout"},"interiorWoodType":{"value":"Natuurlijk, onbehandeld hout (vuren, Siberische ceder of thermisch gemodificeerd lariks)"},"electricalRequirement":{"value":"De standaard houtgestookte Diabaz-kachel heeft geen stroomaansluiting nodig; optioneel een elektrische Harvia-kachel van 9 kW (Cylindro) of 11 kW (Legend Home) met wifi-besturing"},"changingAreaDescription":{"value":"Voorruimte in de uitvoeringen vanaf 300 x 240 cm"}}}'::jsonb, 'Gevel van lamellen van natuurlijk thermohout, binnen natuurlijk onbehandeld hout, houten vloer', 'Plat dak met plaatbedekking', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('4a89f959-21d3-4af0-9cb2-9d996293b9ac', '0e749a4a-c43d-5a70-a687-0caae97c2bfe', 'en', NULL, 'A modern sauna in the form of a small house with a frame construction, made with care for durability and comfort. The facade of natural wood gives it a warm look and blends into the surroundings, while good insulation ensures quick heating and heat retention. Large glazing brightens the interior. The Diabaz stove is fed from the outside. A good choice for a garden, a wellness zone or a leisure facility.', '2026-11-11T10:16:27.977Z'::timestamptz, '2026-11-11T10:16:27.977Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The sauna is placed on a stable, level base prepared by the customer (e.g. a slab, paving or point foundations)', '{"specs":{"glazingType":{"value":"Large glazing; glass door"},"benchMaterial":{"value":"Wooden benches in natural, untreated wood"},"insulationType":{"value":"Wooden walls almost 5 cm thick; the sauna heats up to 80-110 °C in 30-45 minutes"},"claddingMaterial":{"value":"Natural wood"},"interiorWoodType":{"value":"Natural, untreated wood (spruce, Siberian cedar or thermally modified larch)"},"electricalRequirement":{"value":"The standard wood-fired Diabaz stove needs no power supply; an optional Harvia electric stove, 9 kW (Cylindro) or 11 kW (Legend Home), with Wi-Fi control"},"changingAreaDescription":{"value":"Vestibule in the versions from 300 x 240 cm"}}}'::jsonb, 'Frame construction with a natural wood facade, self-supporting wooden base and wooden floor', 'Roof covered with sheet metal or shingle', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('ff5bc77c-9c26-4016-80a3-3aaf13faedfa', '0e749a4a-c43d-5a70-a687-0caae97c2bfe', 'de', NULL, 'Moderne Sauna in Form eines Häuschens mit Rahmenkonstruktion, mit Sorgfalt für Haltbarkeit und Komfort gefertigt. Die Fassade aus Naturholz verleiht ihr ein warmes Aussehen und fügt sich in die Umgebung ein, und die gute Dämmung sorgt für schnelles Aufheizen und Wärmehaltung. Große Verglasungen erhellen den Innenraum. Der Ofen Diabaz wird von außen beschickt. Eine gute Wahl für den Garten, einen Wellnessbereich oder eine Freizeitanlage.', '2026-11-11T10:16:27.977Z'::timestamptz, '2026-11-11T10:16:27.977Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Die Sauna wird auf einem stabilen, ebenen, vom Kunden vorbereiteten Untergrund aufgestellt (z. B. Platte, Pflaster oder Punktfundamente)', '{"specs":{"glazingType":{"value":"Große Verglasungen; Glastür"},"benchMaterial":{"value":"Holzbänke aus naturbelassenem, unbehandeltem Holz"},"insulationType":{"value":"Holzwände von knapp 5 cm Stärke; die Sauna heizt sich in 30-45 Minuten auf 80-110 °C auf"},"claddingMaterial":{"value":"Naturholz"},"interiorWoodType":{"value":"Naturbelassenes, unbehandeltes Holz (Fichte, sibirische Zeder oder thermisch modifizierte Lärche)"},"electricalRequirement":{"value":"Der Standardofen Diabaz (Holzfeuerung) benötigt keinen Stromanschluss; optional Harvia-Elektroofen 9 kW (Cylindro) oder 11 kW (Legend Home) mit WLAN-Steuerung"},"changingAreaDescription":{"value":"Vorraum in den Varianten ab 300 x 240 cm"}}}'::jsonb, 'Rahmenkonstruktion mit Fassade aus Naturholz, selbsttragender Holzsockel und Holzboden', 'Dach mit Blech- oder Schindeldeckung', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('20e58a8b-c104-42e9-bc79-300b56f50391', '0e749a4a-c43d-5a70-a687-0caae97c2bfe', 'nl', NULL, 'Moderne sauna in de vorm van een huisje met een skeletconstructie, met zorg voor duurzaamheid en comfort gebouwd. De gevel van natuurlijk hout geeft haar een warme uitstraling en past in de omgeving, en de goede isolatie zorgt voor snel opwarmen en warmtebehoud. Grote beglazing verlicht het interieur. De Diabaz-kachel wordt van buitenaf gestookt. Een goede keuze voor de tuin, een wellnesszone of een recreatieaccommodatie.', '2026-11-11T10:16:27.977Z'::timestamptz, '2026-11-11T10:16:27.977Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'De sauna wordt geplaatst op een stabiele, vlakke ondergrond die de klant voorbereidt (bijv. een plaat, bestrating of puntfunderingen)', '{"specs":{"glazingType":{"value":"Grote beglazing; glazen deur"},"benchMaterial":{"value":"Houten banken van natuurlijk, onbehandeld hout"},"insulationType":{"value":"Houten wanden van bijna 5 cm dik; de sauna warmt in 30-45 minuten op tot 80-110 °C"},"claddingMaterial":{"value":"Natuurlijk hout"},"interiorWoodType":{"value":"Natuurlijk, onbehandeld hout (vuren, Siberische ceder of thermisch gemodificeerd lariks)"},"electricalRequirement":{"value":"De standaard houtgestookte Diabaz-kachel heeft geen stroomaansluiting nodig; optioneel een elektrische Harvia-kachel van 9 kW (Cylindro) of 11 kW (Legend Home) met wifi-besturing"},"changingAreaDescription":{"value":"Voorruimte in de uitvoeringen vanaf 300 x 240 cm"}}}'::jsonb, 'Skeletconstructie met een gevel van natuurlijk hout, zelfdragende houten basis en houten vloer', 'Dak bedekt met plaat of shingles', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('ad4150c7-19eb-4646-97b7-78c98ddfce48', '8e55d820-22a1-5229-ab9f-2fdcdcb197c4', 'en', NULL, 'A modern garden sauna that combines a modern form with the natural warmth of wood. A solid frame, a facade of wooden elements with graphite details and a flat roof underline the character of the body. Panoramic glazing in dark frames gives lightness and excellent daylight inside. The Diabaz stove is fed from the outside. It suits a private garden as well as wellness zones at commercial facilities.', '2026-11-11T10:16:32.308Z'::timestamptz, '2026-11-11T10:16:32.308Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The sauna is placed on a stable, level base prepared by the customer (e.g. a slab, paving or point foundations)', '{"specs":{"glazingType":{"value":"Panoramic glazing in dark frames; glass door"},"benchMaterial":{"value":"Wooden benches in natural, untreated wood"},"insulationType":{"value":"Wooden walls almost 5 cm thick; the sauna heats up to 80-110 °C in 30-45 minutes"},"claddingMaterial":{"value":"Wooden elements with graphite-coloured details"},"interiorWoodType":{"value":"Natural, untreated wood (spruce, Siberian cedar or thermally modified larch)"},"electricalRequirement":{"value":"The standard wood-fired Diabaz stove needs no power supply; an optional Harvia electric stove, 9 kW (Cylindro) or 11 kW (Legend Home), with Wi-Fi control"},"changingAreaDescription":{"value":"Vestibule in the versions from 324 x 242 cm"}}}'::jsonb, 'Construction on a solid frame, facade of wooden elements with graphite-coloured details, sauna on a stable base', 'Sheet metal roof (colour to choose: RAL 9010, 8017 or 7016)', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('75a42c71-831b-4132-8c50-37cf17082171', '8e55d820-22a1-5229-ab9f-2fdcdcb197c4', 'de', NULL, 'Moderne Gartensauna, die moderne Form mit der natürlichen Wärme von Holz verbindet. Ein solides Gerüst, eine Fassade aus Holzelementen mit graphitfarbenen Details und ein Flachdach unterstreichen den Charakter des Baukörpers. Panoramaverglasungen in dunklen Rahmen sorgen für Leichtigkeit und ausgezeichnete Beleuchtung des Innenraums. Der Ofen Diabaz wird von außen beschickt. Geeignet für den Privatgarten und für Wellnessbereiche bei gewerblichen Anlagen.', '2026-11-11T10:16:32.308Z'::timestamptz, '2026-11-11T10:16:32.308Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Die Sauna wird auf einem stabilen, ebenen, vom Kunden vorbereiteten Untergrund aufgestellt (z. B. Platte, Pflaster oder Punktfundamente)', '{"specs":{"glazingType":{"value":"Panoramaverglasungen in dunklen Rahmen; Glastür"},"benchMaterial":{"value":"Holzbänke aus naturbelassenem, unbehandeltem Holz"},"insulationType":{"value":"Holzwände von knapp 5 cm Stärke; die Sauna heizt sich in 30-45 Minuten auf 80-110 °C auf"},"claddingMaterial":{"value":"Holzelemente mit graphitfarbenen Details"},"interiorWoodType":{"value":"Naturbelassenes, unbehandeltes Holz (Fichte, sibirische Zeder oder thermisch modifizierte Lärche)"},"electricalRequirement":{"value":"Der Standardofen Diabaz (Holzfeuerung) benötigt keinen Stromanschluss; optional Harvia-Elektroofen 9 kW (Cylindro) oder 11 kW (Legend Home) mit WLAN-Steuerung"},"changingAreaDescription":{"value":"Vorraum in den Varianten ab 324 x 242 cm"}}}'::jsonb, 'Konstruktion auf solidem Gerüst, Fassade aus Holzelementen mit graphitfarbenen Details, Sauna auf stabilem Sockel', 'Dach mit Blechdeckung (Farbe nach Wahl: RAL 9010, 8017 oder 7016)', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('e1ccaee0-39ed-4655-a5a0-f2dc1cd7684e', '8e55d820-22a1-5229-ab9f-2fdcdcb197c4', 'nl', NULL, 'Moderne tuinsauna die een moderne vorm combineert met de natuurlijke warmte van hout. Een stevig skelet, een gevel van houten elementen met grafietkleurige details en een plat dak benadrukken het karakter van het volume. Panoramische beglazing in donkere kozijnen geeft lichtheid en uitstekende daglichttoetreding. De Diabaz-kachel wordt van buitenaf gestookt. Geschikt voor de privétuin en voor wellnesszones bij commerciële accommodaties.', '2026-11-11T10:16:32.308Z'::timestamptz, '2026-11-11T10:16:32.308Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'De sauna wordt geplaatst op een stabiele, vlakke ondergrond die de klant voorbereidt (bijv. een plaat, bestrating of puntfunderingen)', '{"specs":{"glazingType":{"value":"Panoramische beglazing in donkere kozijnen; glazen deur"},"benchMaterial":{"value":"Houten banken van natuurlijk, onbehandeld hout"},"insulationType":{"value":"Houten wanden van bijna 5 cm dik; de sauna warmt in 30-45 minuten op tot 80-110 °C"},"claddingMaterial":{"value":"Houten elementen met grafietkleurige details"},"interiorWoodType":{"value":"Natuurlijk, onbehandeld hout (vuren, Siberische ceder of thermisch gemodificeerd lariks)"},"electricalRequirement":{"value":"De standaard houtgestookte Diabaz-kachel heeft geen stroomaansluiting nodig; optioneel een elektrische Harvia-kachel van 9 kW (Cylindro) of 11 kW (Legend Home) met wifi-besturing"},"changingAreaDescription":{"value":"Voorruimte in de uitvoeringen vanaf 324 x 242 cm"}}}'::jsonb, 'Constructie op een stevig skelet, gevel van houten elementen met grafietkleurige details, sauna op een stabiele basis', 'Dak met plaatbedekking (kleur naar keuze: RAL 9010, 8017 of 7016)', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('9cfdf5cc-4930-45df-8983-20a62b8dcb35', 'cbfdb752-e05b-5a16-a841-bcba4847e530', 'en', NULL, 'A modern, free-standing sauna with a compact, rounded body. The structure on a dark metal frame contrasts with horizontal panels of natural wood. Large glass doors give lightness and let light into the interior, where light wood dominates, with two-level benches and a stove in the corner. The whole is kept in a minimalist, Scandinavian style, with an emphasis on natural materials and comfort of use. The Diabaz stove is fed from the outside.', '2026-11-11T10:16:35.419Z'::timestamptz, '2026-11-11T10:16:35.419Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The sauna is placed on a stable, level base prepared by the customer (e.g. a slab, paving or point foundations)', '{"specs":{"glazingType":{"value":"Large glass exterior door"},"benchMaterial":{"value":"Two-level benches of natural wood"},"insulationType":{"value":"Wooden walls almost 5 cm thick; the sauna heats up to 80-110 °C in 30-45 minutes"},"claddingMaterial":{"value":"Horizontal panels of natural wood on a dark metal frame"},"interiorWoodType":{"value":"Natural, untreated wood (spruce, Siberian cedar or thermally modified larch)"},"electricalRequirement":{"value":"The standard wood-fired Diabaz stove needs no power supply; an optional Harvia electric stove, 9 kW (Cylindro) or 11 kW (Legend Home), with Wi-Fi control"},"changingAreaDescription":{"value":"Vestibule in the SO-R3P and SO-R4P versions"}}}'::jsonb, 'Dark metal frame with horizontal panels of natural wood; light wood inside, two-level benches', 'Rounded body with a metal frame', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('4e46d963-828e-460e-a2c3-f5ff13e9c2d8', 'cbfdb752-e05b-5a16-a841-bcba4847e530', 'de', NULL, 'Moderne, freistehende Sauna mit kompaktem, abgerundetem Baukörper. Die Konstruktion auf dunklem Metallrahmen kontrastiert mit waagerechten Paneelen aus Naturholz. Große Glastüren sorgen für Leichtigkeit und lassen Licht in den Innenraum, in dem helles Holz dominiert, mit zweistufigen Bänken und einem Ofen in der Ecke. Das Ganze ist im minimalistischen, skandinavischen Stil gehalten, mit Schwerpunkt auf natürlichen Materialien und Nutzungskomfort. Der Ofen Diabaz wird von außen beschickt.', '2026-11-11T10:16:35.419Z'::timestamptz, '2026-11-11T10:16:35.419Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Die Sauna wird auf einem stabilen, ebenen, vom Kunden vorbereiteten Untergrund aufgestellt (z. B. Platte, Pflaster oder Punktfundamente)', '{"specs":{"glazingType":{"value":"Große gläserne Außentür"},"benchMaterial":{"value":"Zweistufige Bänke aus Naturholz"},"insulationType":{"value":"Holzwände von knapp 5 cm Stärke; die Sauna heizt sich in 30-45 Minuten auf 80-110 °C auf"},"claddingMaterial":{"value":"Waagerechte Paneele aus Naturholz auf dunklem Metallrahmen"},"interiorWoodType":{"value":"Naturbelassenes, unbehandeltes Holz (Fichte, sibirische Zeder oder thermisch modifizierte Lärche)"},"electricalRequirement":{"value":"Der Standardofen Diabaz (Holzfeuerung) benötigt keinen Stromanschluss; optional Harvia-Elektroofen 9 kW (Cylindro) oder 11 kW (Legend Home) mit WLAN-Steuerung"},"changingAreaDescription":{"value":"Vorraum in den Varianten SO-R3P und SO-R4P"}}}'::jsonb, 'Dunkler Metallrahmen mit waagerechten Paneelen aus Naturholz; innen helles Holz, zweistufige Bänke', 'Abgerundeter Baukörper mit Metallrahmen', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('05a4dc0d-1765-4fe0-a840-5f38c6362c66', 'cbfdb752-e05b-5a16-a841-bcba4847e530', 'nl', NULL, 'Moderne, vrijstaande sauna met een compact, afgerond volume. De constructie op een donker metalen frame contrasteert met horizontale panelen van natuurlijk hout. Grote glazen deuren geven lichtheid en laten licht in het interieur, waar licht hout overheerst, met banken op twee niveaus en een kachel in de hoek. Het geheel is in een minimalistische, Scandinavische stijl gehouden, met nadruk op natuurlijke materialen en gebruiksgemak. De Diabaz-kachel wordt van buitenaf gestookt.', '2026-11-11T10:16:35.419Z'::timestamptz, '2026-11-11T10:16:35.419Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'De sauna wordt geplaatst op een stabiele, vlakke ondergrond die de klant voorbereidt (bijv. een plaat, bestrating of puntfunderingen)', '{"specs":{"glazingType":{"value":"Grote glazen buitendeur"},"benchMaterial":{"value":"Banken op twee niveaus van natuurlijk hout"},"insulationType":{"value":"Houten wanden van bijna 5 cm dik; de sauna warmt in 30-45 minuten op tot 80-110 °C"},"claddingMaterial":{"value":"Horizontale panelen van natuurlijk hout op een donker metalen frame"},"interiorWoodType":{"value":"Natuurlijk, onbehandeld hout (vuren, Siberische ceder of thermisch gemodificeerd lariks)"},"electricalRequirement":{"value":"De standaard houtgestookte Diabaz-kachel heeft geen stroomaansluiting nodig; optioneel een elektrische Harvia-kachel van 9 kW (Cylindro) of 11 kW (Legend Home) met wifi-besturing"},"changingAreaDescription":{"value":"Voorruimte in de uitvoeringen SO-R3P en SO-R4P"}}}'::jsonb, 'Donker metalen frame met horizontale panelen van natuurlijk hout; binnen licht hout, banken op twee niveaus', 'Afgerond volume met een metalen frame', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('080ed19d-020c-4510-adea-dfa6b79b0d22', '6a3e6b8e-160d-56f4-af96-be78259d455f', 'en', NULL, 'An oval sauna with a round, panoramic convex polycarbonate glazing. The vertical walls are made of glued timber with a proprietary, waterproof beam joint that prevents water and rain moisture from getting in and counteracts the effects of wood drying out; the solution is protected under Polish law. You can use the wood-fired Diabaz stove or a Harvia electric one.', '2026-11-11T10:16:41.987Z'::timestamptz, '2026-11-11T10:16:41.987Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The sauna is placed on a stable, level base prepared by the customer (e.g. a slab, paving or point foundations)', '{"specs":{"glazingType":{"value":"Convex polycarbonate glazing; glass exterior and interior doors"},"benchMaterial":{"value":"Wooden benches in natural, untreated wood"},"insulationType":{"value":"Wooden walls almost 5 cm thick; the sauna heats up to 80-110 °C in 30-45 minutes"},"claddingMaterial":{"value":"Glued timber, vertical walls with a waterproof beam joint"},"interiorWoodType":{"value":"Natural, untreated wood (spruce, Siberian cedar or thermally modified larch)"},"electricalRequirement":{"value":"The standard wood-fired Diabaz stove needs no power supply; an optional Harvia electric stove, 9 kW (Cylindro) or 11 kW (Legend Home), with Wi-Fi control"},"changingAreaDescription":{"value":"Vestibule in both versions"}}}'::jsonb, 'Vertical walls of glued timber with a proprietary, waterproof beam joint (solution protected under Polish law); convex polycarbonate glazing', 'No covering in the base price; sheet metal or bitumen shingle covering (colour to choose) as an option', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('0d5b834d-0973-41f9-a095-188b901ce649', '6a3e6b8e-160d-56f4-af96-be78259d455f', 'de', NULL, 'Ovale Sauna mit runder, panoramischer, gewölbter Polycarbonat-Verglasung. Die senkrechten Wände bestehen aus Brettschichtholz mit einer eigenen, wasserdichten Balkenverbindung, die das Eindringen von Wasser und Regenfeuchtigkeit verhindert und den Folgen des Austrocknens des Holzes entgegenwirkt; die Lösung ist nach polnischem Recht geschützt. Verwendet werden kann der holzbefeuerte Ofen Diabaz oder ein elektrischer Harvia.', '2026-11-11T10:16:41.987Z'::timestamptz, '2026-11-11T10:16:41.987Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Die Sauna wird auf einem stabilen, ebenen, vom Kunden vorbereiteten Untergrund aufgestellt (z. B. Platte, Pflaster oder Punktfundamente)', '{"specs":{"glazingType":{"value":"Gewölbte Polycarbonat-Verglasung; gläserne Außen- und Innentür"},"benchMaterial":{"value":"Holzbänke aus naturbelassenem, unbehandeltem Holz"},"insulationType":{"value":"Holzwände von knapp 5 cm Stärke; die Sauna heizt sich in 30-45 Minuten auf 80-110 °C auf"},"claddingMaterial":{"value":"Brettschichtholz, senkrechte Wände mit wasserdichter Balkenverbindung"},"interiorWoodType":{"value":"Naturbelassenes, unbehandeltes Holz (Fichte, sibirische Zeder oder thermisch modifizierte Lärche)"},"electricalRequirement":{"value":"Der Standardofen Diabaz (Holzfeuerung) benötigt keinen Stromanschluss; optional Harvia-Elektroofen 9 kW (Cylindro) oder 11 kW (Legend Home) mit WLAN-Steuerung"},"changingAreaDescription":{"value":"Vorraum in beiden Varianten"}}}'::jsonb, 'Senkrechte Wände aus Brettschichtholz mit eigener, wasserdichter Balkenverbindung (nach polnischem Recht geschützte Lösung); gewölbte Polycarbonat-Verglasung', 'Im Grundpreis ohne Dachdeckung; Blech- oder Bitumenschindeldeckung (Farbe nach Wahl) als Option', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('a08a7bee-bba0-420f-bbae-69a37b06e186', '6a3e6b8e-160d-56f4-af96-be78259d455f', 'nl', NULL, 'Ovale sauna met een ronde, panoramische bolle beglazing van polycarbonaat. De verticale wanden zijn gemaakt van gelamineerd hout met een eigen waterdichte verbinding van de balken, die het binnendringen van water en regenvocht voorkomt en de gevolgen van het uitdrogen van het hout tegengaat; de oplossing is naar Pools recht beschermd. Je kunt de houtgestookte Diabaz-kachel of een elektrische Harvia gebruiken.', '2026-11-11T10:16:41.987Z'::timestamptz, '2026-11-11T10:16:41.987Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'De sauna wordt geplaatst op een stabiele, vlakke ondergrond die de klant voorbereidt (bijv. een plaat, bestrating of puntfunderingen)', '{"specs":{"glazingType":{"value":"Bolle beglazing van polycarbonaat; glazen buiten- en binnendeur"},"benchMaterial":{"value":"Houten banken van natuurlijk, onbehandeld hout"},"insulationType":{"value":"Houten wanden van bijna 5 cm dik; de sauna warmt in 30-45 minuten op tot 80-110 °C"},"claddingMaterial":{"value":"Gelamineerd hout, verticale wanden met een waterdichte verbinding van de balken"},"interiorWoodType":{"value":"Natuurlijk, onbehandeld hout (vuren, Siberische ceder of thermisch gemodificeerd lariks)"},"electricalRequirement":{"value":"De standaard houtgestookte Diabaz-kachel heeft geen stroomaansluiting nodig; optioneel een elektrische Harvia-kachel van 9 kW (Cylindro) of 11 kW (Legend Home) met wifi-besturing"},"changingAreaDescription":{"value":"Voorruimte in beide uitvoeringen"}}}'::jsonb, 'Verticale wanden van gelamineerd hout met een eigen waterdichte verbinding van de balken (oplossing beschermd naar Pools recht); bolle beglazing van polycarbonaat', 'Zonder bedekking in de basisprijs; bedekking met plaat of bitumineuze shingles (kleur naar keuze) als optie', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('3fb18e7d-229b-40cb-9199-2fb2407d29fb', 'b5b6eddb-8598-532f-a8ec-884723df939c', 'en', NULL, 'An oval garden sauna with a vestibule that can be used as a Finnish sauna (about 100 °C, humidity 5-10%), a Russian banya (65-80 °C, humidity 10-30%) or a steam sauna. It has supply and exhaust ventilation. The Diabaz stove is fed from the outside, and you can also choose a Harvia electric stove.', '2026-11-11T10:16:44.189Z'::timestamptz, '2026-11-11T10:16:44.189Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The sauna is placed on a stable, level base prepared by the customer (e.g. a slab, paving or point foundations)', '{"specs":{"glazingType":{"value":"Glass exterior and interior doors"},"benchMaterial":{"value":"Wooden benches in natural, untreated wood"},"insulationType":{"value":"Wooden walls almost 5 cm thick; the sauna heats up to 80-110 °C in 30-45 minutes"},"claddingMaterial":{"value":"Natural wood"},"interiorWoodType":{"value":"Natural, untreated wood (spruce, Siberian cedar or thermally modified larch)"},"electricalRequirement":{"value":"The standard wood-fired Diabaz stove needs no power supply; an optional Harvia electric stove, 9 kW (Cylindro) or 11 kW (Legend Home), with Wi-Fi control"},"changingAreaDescription":{"value":"Vestibule"}}}'::jsonb, 'Oval body of natural wood with supply and exhaust ventilation', 'No covering in the base price; sheet metal or bitumen shingle covering (colour to choose) as an option', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('31527f4d-2c8b-4dc1-ad6a-8e262686cb49', 'b5b6eddb-8598-532f-a8ec-884723df939c', 'de', NULL, 'Ovale Gartensauna mit Vorraum, die sich wie eine finnische Sauna (ca. 100 °C, Luftfeuchtigkeit 5-10 %), ein russisches Banja (65-80 °C, Luftfeuchtigkeit 10-30 %) oder eine Dampfsauna nutzen lässt. Sie hat Zu- und Abluftbelüftung. Der Ofen Diabaz wird von außen beschickt, alternativ ist ein elektrischer Harvia-Ofen wählbar.', '2026-11-11T10:16:44.189Z'::timestamptz, '2026-11-11T10:16:44.189Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Die Sauna wird auf einem stabilen, ebenen, vom Kunden vorbereiteten Untergrund aufgestellt (z. B. Platte, Pflaster oder Punktfundamente)', '{"specs":{"glazingType":{"value":"Gläserne Außen- und Innentür"},"benchMaterial":{"value":"Holzbänke aus naturbelassenem, unbehandeltem Holz"},"insulationType":{"value":"Holzwände von knapp 5 cm Stärke; die Sauna heizt sich in 30-45 Minuten auf 80-110 °C auf"},"claddingMaterial":{"value":"Naturholz"},"interiorWoodType":{"value":"Naturbelassenes, unbehandeltes Holz (Fichte, sibirische Zeder oder thermisch modifizierte Lärche)"},"electricalRequirement":{"value":"Der Standardofen Diabaz (Holzfeuerung) benötigt keinen Stromanschluss; optional Harvia-Elektroofen 9 kW (Cylindro) oder 11 kW (Legend Home) mit WLAN-Steuerung"},"changingAreaDescription":{"value":"Vorraum"}}}'::jsonb, 'Ovaler Baukörper aus Naturholz mit Zu- und Abluftbelüftung', 'Im Grundpreis ohne Dachdeckung; Blech- oder Bitumenschindeldeckung (Farbe nach Wahl) als Option', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('adb0dfad-284b-4d0d-bdea-a966f6ae6451', 'b5b6eddb-8598-532f-a8ec-884723df939c', 'nl', NULL, 'Ovale tuinsauna met voorruimte die je kunt gebruiken als Finse sauna (ca. 100 °C, luchtvochtigheid 5-10%), Russische banya (65-80 °C, luchtvochtigheid 10-30%) of stoomsauna. Ze heeft toe- en afvoerventilatie. De Diabaz-kachel wordt van buitenaf gestookt en je kunt ook een elektrische Harvia-kachel kiezen.', '2026-11-11T10:16:44.189Z'::timestamptz, '2026-11-11T10:16:44.189Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'De sauna wordt geplaatst op een stabiele, vlakke ondergrond die de klant voorbereidt (bijv. een plaat, bestrating of puntfunderingen)', '{"specs":{"glazingType":{"value":"Glazen buiten- en binnendeur"},"benchMaterial":{"value":"Houten banken van natuurlijk, onbehandeld hout"},"insulationType":{"value":"Houten wanden van bijna 5 cm dik; de sauna warmt in 30-45 minuten op tot 80-110 °C"},"claddingMaterial":{"value":"Natuurlijk hout"},"interiorWoodType":{"value":"Natuurlijk, onbehandeld hout (vuren, Siberische ceder of thermisch gemodificeerd lariks)"},"electricalRequirement":{"value":"De standaard houtgestookte Diabaz-kachel heeft geen stroomaansluiting nodig; optioneel een elektrische Harvia-kachel van 9 kW (Cylindro) of 11 kW (Legend Home) met wifi-besturing"},"changingAreaDescription":{"value":"Voorruimte"}}}'::jsonb, 'Ovaal volume van natuurlijk hout met toe- en afvoerventilatie', 'Zonder bedekking in de basisprijs; bedekking met plaat of bitumineuze shingles (kleur naar keuze) als optie', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('b90dfa13-83b6-4704-8581-f7936256d28e', 'e0d30621-53a2-5291-ac9e-2a5d3af8595a', 'en', NULL, 'The modular Horyzont sauna allows any space configuration, from size M2 to M6. The interior can be divided into a vestibule and a sauna in 1+2, 2+2, 2+3, 2+4, 3+3 and other layouts, and the sauna door is installed in any module. The Diabaz stove is fed from the outside, and a Harvia electric stove can be chosen as well.', '2026-11-11T10:16:46.088Z'::timestamptz, '2026-11-11T10:16:46.088Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The sauna is placed on a stable, level base prepared by the customer (e.g. a slab, paving or point foundations)', '{"specs":{"glazingType":{"value":"Glass exterior door"},"benchMaterial":{"value":"Wooden benches in natural, untreated wood"},"insulationType":{"value":"Wooden walls almost 5 cm thick; the sauna heats up to 80-110 °C in 30-45 minutes"},"claddingMaterial":{"value":"Natural wood"},"interiorWoodType":{"value":"Natural, untreated wood (spruce, Siberian cedar or thermally modified larch)"},"electricalRequirement":{"value":"The standard wood-fired Diabaz stove needs no power supply; an optional Harvia electric stove, 9 kW (Cylindro) or 11 kW (Legend Home), with Wi-Fi control"},"changingAreaDescription":{"value":"Vestibule in the M4P, M5P and M6P versions; division of the modules to be agreed"}}}'::jsonb, 'Modular construction (modules M2 to M6) of natural wood', 'No covering in the base price; sheet metal or bitumen shingle covering (colour to choose) as an option', 'Any division into vestibule and sauna and any door position in the chosen module; other modular sizes (e.g. M7, M8) on request.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('24411d62-daa6-4803-a69c-18671cc68581', 'e0d30621-53a2-5291-ac9e-2a5d3af8595a', 'de', NULL, 'Die modulare Sauna Horyzont erlaubt eine beliebige Raumkonfiguration, von der Größe M2 bis M6. Der Innenraum lässt sich in Vorraum und Sauna in den Aufteilungen 1+2, 2+2, 2+3, 2+4, 3+3 und weiteren gliedern, und die Saunatür wird in einem beliebigen Modul eingebaut. Der Ofen Diabaz wird von außen beschickt, wählbar ist auch ein elektrischer Harvia-Ofen.', '2026-11-11T10:16:46.088Z'::timestamptz, '2026-11-11T10:16:46.088Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Die Sauna wird auf einem stabilen, ebenen, vom Kunden vorbereiteten Untergrund aufgestellt (z. B. Platte, Pflaster oder Punktfundamente)', '{"specs":{"glazingType":{"value":"Gläserne Außentür"},"benchMaterial":{"value":"Holzbänke aus naturbelassenem, unbehandeltem Holz"},"insulationType":{"value":"Holzwände von knapp 5 cm Stärke; die Sauna heizt sich in 30-45 Minuten auf 80-110 °C auf"},"claddingMaterial":{"value":"Naturholz"},"interiorWoodType":{"value":"Naturbelassenes, unbehandeltes Holz (Fichte, sibirische Zeder oder thermisch modifizierte Lärche)"},"electricalRequirement":{"value":"Der Standardofen Diabaz (Holzfeuerung) benötigt keinen Stromanschluss; optional Harvia-Elektroofen 9 kW (Cylindro) oder 11 kW (Legend Home) mit WLAN-Steuerung"},"changingAreaDescription":{"value":"Vorraum in den Varianten M4P, M5P und M6P; Aufteilung der Module nach Absprache"}}}'::jsonb, 'Modulare Konstruktion (Module M2 bis M6) aus Naturholz', 'Im Grundpreis ohne Dachdeckung; Blech- oder Bitumenschindeldeckung (Farbe nach Wahl) als Option', 'Beliebige Aufteilung in Vorraum und Sauna sowie Türposition im gewählten Modul; weitere Modulgrößen (z. B. M7, M8) auf Anfrage.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('17db7586-e048-4fb0-b205-30bb364dc39b', 'e0d30621-53a2-5291-ac9e-2a5d3af8595a', 'nl', NULL, 'De modulaire sauna Horyzont maakt elke ruimte-indeling mogelijk, van maat M2 tot M6. Het interieur kan worden verdeeld in voorruimte en sauna in indelingen 1+2, 2+2, 2+3, 2+4, 3+3 en andere, en de saunadeur wordt in een willekeurige module geplaatst. De Diabaz-kachel wordt van buitenaf gestookt en je kunt ook een elektrische Harvia-kachel kiezen.', '2026-11-11T10:16:46.088Z'::timestamptz, '2026-11-11T10:16:46.088Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'De sauna wordt geplaatst op een stabiele, vlakke ondergrond die de klant voorbereidt (bijv. een plaat, bestrating of puntfunderingen)', '{"specs":{"glazingType":{"value":"Glazen buitendeur"},"benchMaterial":{"value":"Houten banken van natuurlijk, onbehandeld hout"},"insulationType":{"value":"Houten wanden van bijna 5 cm dik; de sauna warmt in 30-45 minuten op tot 80-110 °C"},"claddingMaterial":{"value":"Natuurlijk hout"},"interiorWoodType":{"value":"Natuurlijk, onbehandeld hout (vuren, Siberische ceder of thermisch gemodificeerd lariks)"},"electricalRequirement":{"value":"De standaard houtgestookte Diabaz-kachel heeft geen stroomaansluiting nodig; optioneel een elektrische Harvia-kachel van 9 kW (Cylindro) of 11 kW (Legend Home) met wifi-besturing"},"changingAreaDescription":{"value":"Voorruimte in de uitvoeringen M4P, M5P en M6P; verdeling van de modules in overleg"}}}'::jsonb, 'Modulaire constructie (modules M2 tot M6) van natuurlijk hout', 'Zonder bedekking in de basisprijs; bedekking met plaat of bitumineuze shingles (kleur naar keuze) als optie', 'Elke verdeling in voorruimte en sauna en elke deurpositie in de gekozen module; andere modulaire maten (bijv. M7, M8) op aanvraag.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('d21e1c25-0e25-4970-a318-786b70035c7a', '61afb070-511e-5960-a826-1c91e0c79499', 'en', NULL, 'A barrel sauna with a convex polycarbonate glazing 8 mm thick. The window panes are made of safety glass and are athermal. Multi-plane glued doors prevent warping, and a special handle with a press and a rubber seal ensures tightness. The Diabaz stove is fed from the outside, and a Harvia electric stove can be chosen as well.', '2026-11-11T10:16:49.680Z'::timestamptz, '2026-11-11T10:16:49.680Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The sauna is placed on a stable, level base prepared by the customer (e.g. a slab, paving or point foundations)', '{"specs":{"glazingType":{"value":"Convex 8 mm polycarbonate glazing; athermal safety glass panes; glass exterior door"},"benchMaterial":{"value":"Wooden benches in natural, untreated wood"},"insulationType":{"value":"Wooden walls almost 5 cm thick; the sauna heats up to 80-110 °C in 30-45 minutes"},"claddingMaterial":{"value":"Natural wood, bitumen shingle or sheet metal roof"},"interiorWoodType":{"value":"Natural, untreated wood (spruce, Siberian cedar or thermally modified larch)"},"electricalRequirement":{"value":"The standard wood-fired Diabaz stove needs no power supply; an optional Harvia electric stove, 9 kW (Cylindro) or 11 kW (Legend Home), with Wi-Fi control"},"changingAreaDescription":{"value":"Vestibule and porch in the 4M and 5M versions"}}}'::jsonb, 'Barrel of natural wood with 8 mm convex polycarbonate glazing, athermal safety glass panes, multi-plane glued doors', 'No covering in the base price; sheet metal or bitumen shingle covering (colour to choose) as an option', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('d6e2fce1-237f-44bb-92e1-f39d73cd4d60', '61afb070-511e-5960-a826-1c91e0c79499', 'de', NULL, 'Fasssauna mit gewölbter Polycarbonat-Verglasung von 8 mm Stärke. Die Fensterscheiben bestehen aus Sicherheitsglas und sind athermisch. Mehrfach verleimte Türen verhindern Verzug, und ein spezieller Griff mit Anpressung und Gummidichtung sorgt für Dichtheit. Der Ofen Diabaz wird von außen beschickt, wählbar ist auch ein elektrischer Harvia-Ofen.', '2026-11-11T10:16:49.680Z'::timestamptz, '2026-11-11T10:16:49.680Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Die Sauna wird auf einem stabilen, ebenen, vom Kunden vorbereiteten Untergrund aufgestellt (z. B. Platte, Pflaster oder Punktfundamente)', '{"specs":{"glazingType":{"value":"Gewölbte 8-mm-Polycarbonat-Verglasung; athermische Sicherheitsglasscheiben; gläserne Außentür"},"benchMaterial":{"value":"Holzbänke aus naturbelassenem, unbehandeltem Holz"},"insulationType":{"value":"Holzwände von knapp 5 cm Stärke; die Sauna heizt sich in 30-45 Minuten auf 80-110 °C auf"},"claddingMaterial":{"value":"Naturholz, Dach aus Bitumenschindeln oder Blech"},"interiorWoodType":{"value":"Naturbelassenes, unbehandeltes Holz (Fichte, sibirische Zeder oder thermisch modifizierte Lärche)"},"electricalRequirement":{"value":"Der Standardofen Diabaz (Holzfeuerung) benötigt keinen Stromanschluss; optional Harvia-Elektroofen 9 kW (Cylindro) oder 11 kW (Legend Home) mit WLAN-Steuerung"},"changingAreaDescription":{"value":"Vorraum und Vorbau in den Varianten 4M und 5M"}}}'::jsonb, 'Fass aus Naturholz mit gewölbter 8-mm-Polycarbonat-Verglasung, athermische Sicherheitsglasscheiben, mehrfach verleimte Türen', 'Im Grundpreis ohne Dachdeckung; Blech- oder Bitumenschindeldeckung (Farbe nach Wahl) als Option', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('543316fe-3753-478c-b616-b5b090d932c5', '61afb070-511e-5960-a826-1c91e0c79499', 'nl', NULL, 'Vatsauna met een bolle beglazing van polycarbonaat van 8 mm dik. De ruiten zijn van veiligheidsglas en athermisch. Meervlaksverlijmde deuren voorkomen vervorming en een speciale klink met aandrukking en rubberen afdichting zorgt voor dichtheid. De Diabaz-kachel wordt van buitenaf gestookt en je kunt ook een elektrische Harvia-kachel kiezen.', '2026-11-11T10:16:49.680Z'::timestamptz, '2026-11-11T10:16:49.680Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'De sauna wordt geplaatst op een stabiele, vlakke ondergrond die de klant voorbereidt (bijv. een plaat, bestrating of puntfunderingen)', '{"specs":{"glazingType":{"value":"Bolle beglazing van polycarbonaat 8 mm; athermische veiligheidsglasruiten; glazen buitendeur"},"benchMaterial":{"value":"Houten banken van natuurlijk, onbehandeld hout"},"insulationType":{"value":"Houten wanden van bijna 5 cm dik; de sauna warmt in 30-45 minuten op tot 80-110 °C"},"claddingMaterial":{"value":"Natuurlijk hout, dak van bitumineuze shingles of plaat"},"interiorWoodType":{"value":"Natuurlijk, onbehandeld hout (vuren, Siberische ceder of thermisch gemodificeerd lariks)"},"electricalRequirement":{"value":"De standaard houtgestookte Diabaz-kachel heeft geen stroomaansluiting nodig; optioneel een elektrische Harvia-kachel van 9 kW (Cylindro) of 11 kW (Legend Home) met wifi-besturing"},"changingAreaDescription":{"value":"Voorruimte en portaal in de uitvoeringen 4M en 5M"}}}'::jsonb, 'Vat van natuurlijk hout met 8 mm bolle beglazing van polycarbonaat, athermische veiligheidsglasruiten, meervlaksverlijmde deuren', 'Zonder bedekking in de basisprijs; bedekking met plaat of bitumineuze shingles (kleur naar keuze) als optie', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('b47de971-85fb-45d7-bd58-0ad422660463', '65b635a4-fcf6-5222-adf5-10d5feae09c9', 'en', NULL, 'A barrel sauna with the in-house Diabaz stove: suitable for pouring water directly and keeps the desired humidity thanks to a dosing evaporator. The filling and inspection openings are on the outside, so there is no need to carry fuel into the sauna or air it out, and operating the stove from outside keeps smoke out of the interior. A Harvia electric stove is available as well.', '2026-11-11T10:16:51.244Z'::timestamptz, '2026-11-11T10:16:51.244Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The sauna is placed on a stable, level base prepared by the customer (e.g. a slab, paving or point foundations)', '{"specs":{"glazingType":{"value":"Glass exterior door"},"benchMaterial":{"value":"Wooden benches in natural, untreated wood"},"insulationType":{"value":"Wooden walls almost 5 cm thick; the sauna heats up to 80-110 °C in 30-45 minutes"},"claddingMaterial":{"value":"Natural wood, bitumen shingle or sheet metal roof"},"interiorWoodType":{"value":"Natural, untreated wood (spruce, Siberian cedar or thermally modified larch)"},"electricalRequirement":{"value":"The standard wood-fired Diabaz stove needs no power supply; an optional Harvia electric stove, 9 kW (Cylindro) or 11 kW (Legend Home), with Wi-Fi control"},"changingAreaDescription":{"value":"Vestibule in the SO-3B and SO-4B versions"}}}'::jsonb, 'Barrel of natural wood with a Diabaz stove operated from the outside', 'No covering in the base price; sheet metal or bitumen shingle covering (colour to choose) as an option', 'Optionally an additional canopy, a vestibule and a glazed front or back (surcharges according to the producer''s price list).', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('869c41ec-a93a-4a5d-bc5c-ace7dee33dbe', '65b635a4-fcf6-5222-adf5-10d5feae09c9', 'de', NULL, 'Fasssauna mit dem hauseigenen Ofen Diabaz: Er eignet sich zum direkten Aufgießen und hält dank eines dosierenden Verdampfers die gewünschte Feuchtigkeit. Beschickungs- und Revisionsöffnung liegen außen, sodass man weder Brennstoff in die Sauna tragen noch sie lüften muss, und die Bedienung des Ofens von außen verhindert, dass Rauch in den Innenraum gelangt. Wählbar ist auch ein elektrischer Harvia-Ofen.', '2026-11-11T10:16:51.244Z'::timestamptz, '2026-11-11T10:16:51.244Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Die Sauna wird auf einem stabilen, ebenen, vom Kunden vorbereiteten Untergrund aufgestellt (z. B. Platte, Pflaster oder Punktfundamente)', '{"specs":{"glazingType":{"value":"Gläserne Außentür"},"benchMaterial":{"value":"Holzbänke aus naturbelassenem, unbehandeltem Holz"},"insulationType":{"value":"Holzwände von knapp 5 cm Stärke; die Sauna heizt sich in 30-45 Minuten auf 80-110 °C auf"},"claddingMaterial":{"value":"Naturholz, Dach aus Bitumenschindeln oder Blech"},"interiorWoodType":{"value":"Naturbelassenes, unbehandeltes Holz (Fichte, sibirische Zeder oder thermisch modifizierte Lärche)"},"electricalRequirement":{"value":"Der Standardofen Diabaz (Holzfeuerung) benötigt keinen Stromanschluss; optional Harvia-Elektroofen 9 kW (Cylindro) oder 11 kW (Legend Home) mit WLAN-Steuerung"},"changingAreaDescription":{"value":"Vorraum in den Varianten SO-3B und SO-4B"}}}'::jsonb, 'Fass aus Naturholz mit von außen bedientem Ofen Diabaz', 'Im Grundpreis ohne Dachdeckung; Blech- oder Bitumenschindeldeckung (Farbe nach Wahl) als Option', 'Optional ein zusätzliches Vordach, ein Vorraum sowie eine verglaste Front oder Rückseite (Aufpreise laut Preisliste des Herstellers).', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('0702dcce-f1fa-487e-92f6-32f72d7429ca', '65b635a4-fcf6-5222-adf5-10d5feae09c9', 'nl', NULL, 'Vatsauna met de eigen Diabaz-kachel: geschikt om rechtstreeks water op te gieten en houdt de gewenste vochtigheid dankzij een doserende verdamper. De vul- en inspectieopeningen zitten aan de buitenkant, dus je hoeft geen brandstof de sauna in te dragen of te luchten, en de bediening van de kachel van buitenaf houdt rook uit het interieur. Ook een elektrische Harvia-kachel is beschikbaar.', '2026-11-11T10:16:51.244Z'::timestamptz, '2026-11-11T10:16:51.244Z'::timestamptz, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'De sauna wordt geplaatst op een stabiele, vlakke ondergrond die de klant voorbereidt (bijv. een plaat, bestrating of puntfunderingen)', '{"specs":{"glazingType":{"value":"Glazen buitendeur"},"benchMaterial":{"value":"Houten banken van natuurlijk, onbehandeld hout"},"insulationType":{"value":"Houten wanden van bijna 5 cm dik; de sauna warmt in 30-45 minuten op tot 80-110 °C"},"claddingMaterial":{"value":"Natuurlijk hout, dak van bitumineuze shingles of plaat"},"interiorWoodType":{"value":"Natuurlijk, onbehandeld hout (vuren, Siberische ceder of thermisch gemodificeerd lariks)"},"electricalRequirement":{"value":"De standaard houtgestookte Diabaz-kachel heeft geen stroomaansluiting nodig; optioneel een elektrische Harvia-kachel van 9 kW (Cylindro) of 11 kW (Legend Home) met wifi-besturing"},"changingAreaDescription":{"value":"Voorruimte in de uitvoeringen SO-3B en SO-4B"}}}'::jsonb, 'Vat van natuurlijk hout met een Diabaz-kachel die van buitenaf wordt bediend', 'Zonder bedekking in de basisprijs; bedekking met plaat of bitumineuze shingles (kleur naar keuze) als optie', 'Optioneel een extra afdakje, een voorruimte en een beglaasde voor- of achterzijde (meerprijzen volgens de prijslijst van de producent).', NULL) ON CONFLICT DO NOTHING;
